            expect(componentProps).toBeDefined()

            const props = JSON.parse(componentProps)

            // Verify user props override defaults
            expect(props.showLegend).toBe(false) // overridden from default true
            expect(props.headingLevel).toBe(3) // overridden from default 2
            expect(props.chartVariation).toBe('line') // overridden from default 'stacked'
